 const [query,setQuery]=useState(''),[stageFilter,setStageFilter]=useState('All stages'),[leadFilter,setLeadFilter]=useState('All leads'),[sort,setSort]=useState('Newest first'),[sidebar,setSidebar]=useState(false),[theme,setTheme]=useState('light');
 const [modal,setModal]=useState<'lead'|'task'|'property'|'import'|'help'|null>(null),[editing,setEditing]=useState<Lead|undefined>(),[detailId,setDetailId]=useState(''),[deleteId,setDeleteId]=useState(''),[propertyId,setPropertyId]=useState(''),[propertyLead,setPropertyLead]=useState(''),[taskLead,setTaskLead]=useState(''),[taskDate,setTaskDate]=useState(day());
