 async function refresh(){if(demo){const sample=seedWorkspace();let state=sample;try{const cached=sessionStorage.getItem('estateflow-demo-v2');if(cached)state=workspaceSchema.parse(JSON.parse(cached));}catch{}stateRef.current=state;setData(state);setSettingsEdit(state.settings);setScope('demo');setLoading(false);return;}setLoading(true);setLoadError('');try{const r=await fetch('/api/workspace',{cache:'no-store'});const result=await r.json() as {state:Workspace;revision:number;workspaceId:string;error?:string};if(!r.ok)throw new Error(result.error);stateRef.current=result.state;setData(result.state);revision.current=result.revision;setSettingsEdit(result.state.settings);setScope(result.workspaceId);}catch(e){setLoadError(e instanceof Error?e.message:'Could not load the workspace.');}finally{setLoading(false);}}
 useEffect(()=>{void refresh();try{const pref=localStorage.getItem('estateflow-theme')||'light';setTheme(pref);document.documentElement.dataset.theme=pref;setAiOpen(localStorage.getItem('estateflow-assistant-open')!=='false');}catch{}const timer=setInterval(()=>setToday(day()),60000);return()=>clearInterval(timer);},[]);
