 async function toggleTask(t:Task){await mutate(s=>({...s,tasks:s.tasks.map(x=>x.id===t.id?{...x,done:!t.done}:x),activities:[activity(t.leadId,`${t.done?'Reopened':'Completed'}: ${t.title}`,'task'),...s.activities].slice(0,1000)}),t.done?'Task reopened':'One more next step, done');}
