 async function createStoredDraft(leadId:string,subject:string,body:string,provider='Template'){const lead=stateRef.current?.leads.find(l=>l.id===leadId);if(!lead)return false;const id=uid();const result=await mutate(s=>({...s,drafts:[{id,leadId,subject,body:body.replaceAll('[First Name]',lead.name.split(' ')[0]).replaceAll('[Agent Name]',s.settings.name),status:'Needs review',createdAt:day(),provider},...s.drafts],activities:[activity(leadId,`Draft prepared for ${lead.name}`,'draft'),...s.activities].slice(0,1000)}),'Draft saved for your review');if(result){setDraftId(id);go('Drafts');}return result;}
 function makeDraft(lead:Lead){toggleAI(true);setAssistantRequest({id:uid(),leadId:lead.id});}
 async function confirmProposal(p:AssistantProposal){const lead=stateRef.current?.leads.find(l=>l.id===p.leadId);if(!lead){notify('This lead is no longer available.',true);return false;}return await mutate(s=>p.type==='stage'?({...s,leads:s.leads.map(l=>l.id===p.leadId?{...l,stage:p.stage}:l),activities:[activity(lead.id,lead.name+' moved to '+p.stage,'stage'),...s.activities].slice(0,1000)}):({...s,tasks:[{id:uid(),leadId:p.leadId,title:p.title,due:p.dueDate,time:'09:00',done:false,kind:'Task' as const},...s.tasks],activities:[activity(lead.id,'Scheduled: '+p.title,'task'),...s.activities].slice(0,1000)}),'Change saved');}
 async function readNotifications(keys:string[]){if(!keys.length)return true;return await mutate(s=>({...s,settings:{...s.settings,notificationReads:Array.from(new Set([...(s.settings.notificationReads||[]),...keys])).slice(-3000)}}),'');}
 async function connectAI(){if(demo){notify('Sign in to a saved workspace to connect live AI.',true);return;}if(!keyInput.trim())return notify('Paste your Google AI Studio key first.',true);setConnecting(true);try{const key=keyInput.trim();const r=await fetch('/api/ai/connect',{method:'POST',headers:{'x-ai-key':key}});const result=await r.json() as {error?:string;model:string};if(!r.ok)throw new Error(result.error);setAiKey(key);try{sessionStorage.setItem('estateflow-ai:'+scope,JSON.stringify({key,model:result.model}));}catch{}setModel(result.model);setKeyInput('');notify(`Gemini connected · ${result.model}`);}catch(e){notify(e instanceof Error?e.message:'Could not connect AI.',true);}finally{setConnecting(false);}}
 function exportCSV(){const headers=['Lead ID','Full Name','Email','Phone','Budget','Preferred Area','Property Type','Timeline','Status','Source','Submitted At','Last Contacted','Next Follow-Up','Notes'];const protect=(v:unknown)=>{const s=String(v??'');return '"'+(/^[=+\-@]/.test(s)?"'":'')+s.replaceAll('"','""')+'"';};const rows=data!.leads.map(l=>[l.id,l.name,l.email,l.phone,l.budget,l.area,l.type,l.timeline,l.stage,l.source,l.createdAt,l.lastContact,l.followUp,l.notes]);download(`EstateFlow_Leads_${day()}.csv`,[headers,...rows].map(r=>r.map(protect).join(',')).join('\r\n'),'text/csv;charset=utf-8');notify('Lead tracker exported');}
