 async function importFile(file:File){try{if(file.size>2e6)throw new Error('Choose a CSV smaller than 2 MB.');const rows=parseCSV(await file.text());if(rows.length<2)throw new Error('The CSV needs a header and at least one lead.');const headers=rows[0].map(h=>h.replace(/^\uFEFF/,'').trim().toLowerCase());const get=(row:string[],...names:string[])=>{for(const name of names){const i=headers.indexOf(name);if(i>=0&&row[i])return row[i].trim();}return '';};const dateValue=(v:string)=>{if(!v)return '';const d=new Date(v);return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,10);};let skipped=0;const candidates:Lead[]=[];for(const row of rows.slice(1)){const name=get(row,'full name','name')||[get(row,'first name'),get(row,'last name')].filter(Boolean).join(' ');const email=get(row,'email','email address');if(!name||data!.leads.some(l=>email&&l.email.toLowerCase()===email.toLowerCase())||candidates.some(l=>email&&l.email.toLowerCase()===email.toLowerCase())){skipped++;continue;}const raw=get(row,'budget','budget range','maximum budget').replaceAll(',','');const numbers=raw.match(/[\d.]+/g)||['0'];const budget=Number(numbers[numbers.length-1])*(/m|million/i.test(raw)?1e6:1);const status=get(row,'status','stage');candidates.push({id:uid(),name,email,phone:get(row,'phone','phone number'),area:get(row,'preferred area','area')||'Not specified',type:get(row,'property type','type')||'Condominium',budget:Number.isFinite(budget)?budget:0,timeline:get(row,'timeline','purchase timeline')||'Still exploring',stage:STAGES.includes(status as Lead['stage'])?status as Lead['stage']:'New',source:get(row,'source')||'Google Forms',createdAt:dateValue(get(row,'submitted at','timestamp'))||day(),lastContact:dateValue(get(row,'last contacted')),followUp:dateValue(get(row,'next follow-up'))||day(1),notes:get(row,'notes'),tags:['Imported']});}if(candidates.length+data!.leads.length>1000)throw new Error('A workspace can contain up to 1,000 leads.');const validated=candidates.every(l=>workspaceSchema.shape.leads.element.safeParse(l).success);if(!validated)throw new Error('Some fields are too long or invalid. Check the CSV and try again.');setImportRows(candidates);setImportMessage(`${candidates.length} new leads found. ${skipped} empty or duplicate record${skipped===1?'':'s'} skipped.`);}catch(e){setImportRows([]);setImportMessage(e instanceof Error?e.message:'The CSV could not be read.');}}
 async function restoreBackup(file:File){try{if(file.size>2e6)throw new Error('Backup file is too large.');const value=JSON.parse(await file.text());const state=workspaceSchema.parse(value.workspace||value);if(!window.confirm('Replace your current workspace with this backup? Export your current workspace first if you need to keep it.'))return;const ok=await mutate(()=>state,'Backup restored');if(ok)setSettingsEdit(state.settings);}catch{notify('This is not a valid EstateFlow backup.',true);}if(backupRef.current)backupRef.current.value='';}
 const computed=useMemo(()=>{
  if(!data)return null;
  const leadMap=new Map(data.leads.map(l=>[l.id,l]));
  const openLeads=data.leads.filter(isOpen),dueLeads=openLeads.filter(l=>l.followUp&&l.followUp<=today),overdue=dueLeads.filter(l=>l.followUp<today);
  const openTasks=data.tasks.filter(t=>!t.done).sort((a,b)=>(a.due+a.time).localeCompare(b.due+b.time)),dueTasks=openTasks.filter(t=>t.due<=today);
  const closed=data.leads.length-openLeads.length,won=data.leads.filter(l=>l.stage==='Won').length,conversion=closed?Math.round(won/closed*100):0;
  const term=deferredQuery.toLowerCase();
  const visibleLeads=data.leads.filter(l=>(!term||[l.name,l.email,l.area,l.type,...l.tags].join(' ').toLowerCase().includes(term))&&(stageFilter==='All stages'||l.stage===stageFilter)&&(leadFilter==='All leads'||leadFilter==='Needs attention'&&isOpen(l)&&l.followUp&&l.followUp<=today||leadFilter==='Recently added'&&l.createdAt>=day(-7))).sort((a,b)=>sort==='Name A–Z'?a.name.localeCompare(b.name):sort==='Highest budget'?b.budget-a.budget:b.createdAt.localeCompare(a.createdAt));
  const filteredDrafts=data.drafts.filter(d=>draftTab==='All drafts'?d.status!=='Archived':d.status===draftTab);
  const filteredTasks=data.tasks.filter(t=>followTab==='Completed'?t.done:!t.done&&(followTab==='All'||followTab==='Overdue'&&t.due<today||followTab==='Today'&&t.due===today||followTab==='Upcoming'&&t.due>today)).sort((a,b)=>(a.due+a.time).localeCompare(b.due+b.time));
  const focus=leadMap.get(propertyLead);
  const matchedProperties=data.properties.map(property=>({property,match:focus?matchProperty(focus,property):undefined})).sort((a,b)=>(b.match?.score||0)-(a.match?.score||0));
  return {leadMap,openLeads,dueLeads,overdue,openTasks,dueTasks,closed,won,conversion,visibleLeads,filteredDrafts,filteredTasks,matchedProperties};
 },[data,today,deferredQuery,stageFilter,leadFilter,sort,draftTab,followTab,propertyLead]);
 if(loading&&!data)return <div className="loading-screen"><Logo/><span className="spinner"/><p>Loading workspace…</p></div>;
 if(loadError&&!data)return <div className="loading-screen"><Logo/><AlertCircle size={35}/><h2>Workspace unavailable</h2><p>{loadError}</p><button className="button primary" onClick={()=>void refresh()}>Try again<RefreshCw size={16}/></button><a href="/login">Sign in again</a></div>;
 if(!data||!computed)return null;
 const {leadMap,openLeads,dueLeads,overdue,openTasks,dueTasks,closed,won,conversion,visibleLeads,filteredDrafts,filteredTasks,matchedProperties}=computed;
 const detail=leadMap.get(detailId),selectedProperty=data.properties.find(p=>p.id===propertyId);
